code.python:
def deserialize(data):
    vals = iter(data.split(","))
    def dfs():
        val = next(vals)
        if val == "N": return None
        node = TreeNode(int(val))
        node.left = dfs()
        node.right = dfs()
        return node
    return dfs()

code.javascript:
function deserialize(data) {
    const vals = data.split(",");
    let i = 0;
    function dfs() {
        if (vals[i] === "N") { i++; return null; }
        let node = new TreeNode(parseInt(vals[i++]));
        node.left = dfs();
        node.right = dfs();
        return node;
    }
    return dfs();
}
